package http

import (
	"encoding/json"
	"errors"
	"net/http"
	"net/mail"

	"example.com/app/internal/store"
)

// UserController serves the legacy REST API used by mobile v3.x and the
// partner portal.
type UserController struct {
	Store store.UserStore
}

func (c *UserController) Register(mux *http.ServeMux) {
	mux.HandleFunc("GET /v1/users/{id}", c.getUser)
	mux.HandleFunc("POST /v1/users", c.createUser)
}

type userJSON struct {
	ID          string `json:"id"`
	Email       string `json:"email"`
	DisplayName string `json:"display_name,omitempty"`
	CreatedAt   int64  `json:"created_at"` // unix seconds
}

type errorJSON struct {
	Error string `json:"error"`
}

func writeErr(w http.ResponseWriter, status int, code string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(errorJSON{Error: code})
}

func (c *UserController) getUser(w http.ResponseWriter, r *http.Request) {
	u, err := c.Store.Get(r.Context(), r.PathValue("id"))
	if errors.Is(err, store.ErrNotFound) {
		writeErr(w, http.StatusNotFound, "user_not_found")
		return
	}
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal")
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(userJSON{u.ID, u.Email, u.DisplayName, u.CreatedAt.Unix()})
}

func (c *UserController) createUser(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Email       string `json:"email"`
		DisplayName string `json:"display_name"`
	}
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		writeErr(w, http.StatusBadRequest, "malformed_json")
		return
	}
	if _, err := mail.ParseAddress(in.Email); err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_email")
		return
	}
	u, err := c.Store.Create(r.Context(), in.Email, in.DisplayName)
	if errors.Is(err, store.ErrDuplicateEmail) {
		writeErr(w, http.StatusConflict, "email_taken")
		return
	}
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal")
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(userJSON{u.ID, u.Email, u.DisplayName, u.CreatedAt.Unix()})
}

