"""Legacy REST controller: PATCH /accounts/<id>."""

from flask import Blueprint, jsonify, request

from account import repo

bp = Blueprint("accounts", __name__)
_STATUSES = {"ACTIVE", "INACTIVE"}


@bp.patch("/accounts/<account_id>")
def patch_account(account_id):
  body = request.get_json(force=True) or {}
  acct = repo.get(account_id)
  if acct is None:
    return jsonify(error="not_found"), 404
  # Omitted key: leave unchanged. Explicit null: clear the field.
  if "display_name" in body:
    acct.display_name = body["display_name"]  # may be None -> cleared
  if "billing_email" in body:
    acct.billing_email = body["billing_email"]  # None -> fall back to owner email
  if "status" in body:
    if body["status"] not in _STATUSES:
      return jsonify(error="invalid_status"), 400
    acct.status = body["status"]
  repo.save(acct)
  return jsonify(acct.to_dict())

