import contextlib

_conn = None


def connect(conn):
  global _conn
  _conn = conn


@contextlib.contextmanager
def transaction():
  cur = _conn.cursor()
  try:
    yield cur
    _conn.commit()
  except Exception:
    _conn.rollback()
    raise

