import type { Request, Response, NextFunction } from 'express';
import { verifyBearer } from '../auth/oauth';
import { lookupApiKey } from '../auth/api_keys';

export async function authenticate(req: Request, res: Response, next: NextFunction) {
  const authz = req.header('authorization');
  if (authz?.startsWith('Bearer ')) {
    const principal = await verifyBearer(authz.slice(7));
    if (!principal) return res.status(401).set('WWW-Authenticate', 'Bearer error="invalid_token"').end();
    req.principal = principal;
    return next();
  }
  const apiKey = req.header('x-api-key');
  if (apiKey) {
    const principal = await lookupApiKey(apiKey);
    if (!principal) return res.status(401).end();
    req.principal = principal;
    return next();
  }
  return res.status(401).set('WWW-Authenticate', 'Bearer').end();
}

