// Package apierr writes the canonical JSON error envelope.
package apierr

import (
	"encoding/json"
	"net/http"

	"google.golang.org/grpc/codes"
)

var httpStatus = map[codes.Code]int{
	codes.InvalidArgument:    http.StatusBadRequest,
	codes.NotFound:           http.StatusNotFound,
	codes.AlreadyExists:      http.StatusConflict,
	codes.PermissionDenied:   http.StatusForbidden,
	codes.Unauthenticated:    http.StatusUnauthorized,
	codes.ResourceExhausted:  http.StatusTooManyRequests,
	codes.FailedPrecondition: http.StatusPreconditionFailed,
	codes.Internal:           http.StatusInternalServerError,
}

type envelope struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// Write emits {"code": "NOT_FOUND", "message": "..."} with the mapped status.
func Write(w http.ResponseWriter, c codes.Code, msg string) {
	status, ok := httpStatus[c]
	if !ok {
		status = http.StatusInternalServerError
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(envelope{Code: c.String(), Message: msg})
}

