package presence

import (
	"sync"
	"time"
)

const (
	// HeartbeatInterval is how often clients ping /presence/heartbeat.
	HeartbeatInterval = 15 * time.Second
	// LeaseTTL is how long a PresenceLease stays valid without a heartbeat.
	LeaseTTL = 90 * time.Second
)

// PresenceLease marks one device of a user as online until ExpiresAt.
type PresenceLease struct {
	UserID    string
	DeviceID  string
	ExpiresAt time.Time
}

// Roster tracks active leases. A user is online if any device lease is live.
type Roster struct {
	mu     sync.Mutex
	leases map[string]map[string]PresenceLease // user -> device -> lease
}

func (r *Roster) Heartbeat(userID, deviceID string, now time.Time) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.leases == nil {
		r.leases = map[string]map[string]PresenceLease{}
	}
	if r.leases[userID] == nil {
		r.leases[userID] = map[string]PresenceLease{}
	}
	r.leases[userID][deviceID] = PresenceLease{userID, deviceID, now.Add(LeaseTTL)}
}

func (r *Roster) Online(userID string, now time.Time) bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	for _, l := range r.leases[userID] {
		if now.Before(l.ExpiresAt) {
			return true
		}
	}
	return false
}

