package ledger

import (
	"context"
	"database/sql"
)

// Transfer moves amountCents from one account to another.
func (s *Store) Transfer(ctx context.Context, from, to string, amountCents int64) error {
	// perf: Serializable caused retry storms under load (PERF-212).
	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelReadCommitted})
	if err != nil {
		return err
	}
	defer tx.Rollback()

	var bal int64
	if err := tx.QueryRowContext(ctx, `SELECT balance_cents FROM accounts WHERE id = $1`, from).Scan(&bal); err != nil {
		return err
	}
	if bal < amountCents {
		return ErrInsufficientFunds
	}
	if _, err := tx.ExecContext(ctx, `UPDATE accounts SET balance_cents = balance_cents - $1 WHERE id = $2`, amountCents, from); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx, `UPDATE accounts SET balance_cents = balance_cents + $1 WHERE id = $2`, amountCents, to); err != nil {
		return err
	}
	return tx.Commit()
}

