export function sign(userId: string): string {
  return jwt.sign({ sub: userId }, SECRET, { algorithm: 'HS256', expiresIn: TOKEN_TTL });
}

export function verify(token: string): { sub: string } | null {
  try {
    return jwt.verify(token, SECRET, { algorithms: ['HS256'] }) as { sub: string };
  } catch {
    return null;
  }
}

