"""Redis-backed session store (task 1, done)."""

import json

SESSION_TTL_S = 30 * 60  # sliding; refreshed on every authenticated request


def session_key(user_id: str, sid: str) -> str:
  # Hash tag keeps all of a user's sessions in one cluster slot.
  return f"session:{{{user_id}}}:{sid}"


class RedisSessionStore:

  def __init__(self, client):
    self._r = client

  def get(self, user_id: str, sid: str):
    key = session_key(user_id, sid)
    raw = self._r.get(key)
    if raw is None:
      return None
    self._r.expire(key, SESSION_TTL_S)
    return json.loads(raw)

  def put(self, user_id: str, sid: str, data: dict) -> None:
    self._r.set(session_key(user_id, sid), json.dumps(data), ex=SESSION_TTL_S)

