import type { Request, Response, NextFunction } from 'express';

export function rateLimit(opts: { limit: number; windowS: number }) {
  const hits = new Map<string, { n: number; reset: number }>();
  return (req: Request, res: Response, next: NextFunction) => {
    const now = Date.now() / 1000;
    const k = req.ip ?? 'anon';
    const h = hits.get(k) ?? { n: 0, reset: now + opts.windowS };
    if (now > h.reset) { h.n = 0; h.reset = now + opts.windowS; }
    h.n++;
    hits.set(k, h);
    res.set('RateLimit-Limit', String(opts.limit));
    res.set('RateLimit-Remaining', String(Math.max(0, opts.limit - h.n)));
    res.set('RateLimit-Reset', String(Math.ceil(h.reset - now)));
    if (h.n > opts.limit) return res.status(429).end();
    next();
  };
}

